       letter-spacing: -0.03em;
     }

     .intro {
       margin: 0 0 24px;
       color: var(--muted);
       line-height: 1.5;
     }

     .form-field {
       display: grid;
       gap: 10px;
       padding: 18px;
       border: 1px solid var(--border);
       border-radius: 16px;
       background: linear-gradient(180deg, #fff, #f8fbff);
     }

     .checkbox-row {
       display: flex;
