       gap: 12px;
     }

     .checkbox-row input {
       width: 1.15rem;
       height: 1.15rem;
       margin: 0.2rem 0 0;
       accent-color: var(--accent);
       flex: 0 0 auto;
     }

     .checkbox-row label {
       font-weight: 600;
       line-height: 1.4;
       cursor: pointer;
     }

     .required-mark {
       color: var(--accent);
     }

     .helper-text {
       margin: 0;
       color: var(--muted);
       font-size: 0.95rem;
       line-height: 1.4;
     }

     .error-text {
       margin: 0;
       color: var(--error);
       font-size: 0.95rem;
       line-height: 1.4;
     }

     .actions {
       margin-top: 20px;
       display: flex;
       flex-wrap: wrap;
       gap: 12px;
       align-items: center;
     }

     button {
       appearance: none;
       border: 0;
       border-radius: 999px;
       padding: 0.95rem 1.35rem;
       background: var(--accent);
       color: #fff;
       font: inherit;
       font-weight: 700;
       cursor: pointer;
       box-shadow: 0 12px 24px rgba(37, 99, 235, 0.24);
       transition: transform 120ms ease, background-color 120ms ease, box-shadow 120ms ease;
     }

     button:hover {
       background: var(--accent-hover);
     }

     button:active {
       transform: translateY(1px);
     }

     :focus-visible {
       outline: 3px solid #0f172a;
       outline-offset: 3px;
     }

     .status {
       margin: 0;
       color: #166534;
       font-weight: 600;
     }

     [hidden] {
       display: none !important;
     }

     @media (max-width: 420px) {
       .card {
         padding: 24px;
       }

       .checkbox-row {
         gap: 10px;
       }
     }

     @media (prefers-reduced-motion: reduce) {
       *, *::before, *::after {
         scroll-behavior: auto;
         transition-duration: 0.01ms !important;
         animation-duration: 0.01ms !important;
         animation-iteration-count: 1 !important;
       }
     }
   </style>
 </head>
 <body>
   <main>
     <section class="card" aria-labelledby="page-title">
       <h1 id="page-title">Review and consent</h1>
       <p class="intro">Please confirm that you agree to the Terms of Use before continuing.</p>

       <form id="consent-form" novalidate>
         <div class="form-field">
           <div class="checkbox-row">
             <input
               id="agree-terms"
               name="agreeTerms"
               type="checkbox"
               required
               aria-describedby="agree-help agree-error"
             >
             <label for="agree-terms">
               I agree to the Terms of Use <span class="required-mark" aria-hidden="true">*</span>
             </label>
           </div>

           <p id="agree-help" class="helper-text">This is required to complete the form.</p>
           <p id="agree-error" class="error-text" hidden>Error: You must agree to the Terms of Use to continue.</p>
         </div>

         <div class="actions">
           <button type="submit">Continue</button>
           <p id="form-status" class="status" role="status" aria-live="polite" hidden>Consent saved.</p>
         </div>
       </form>
     </section>
   </main>

   <script>
     const form = document.getElementById('consent-form');
     const checkbox = document.getElementById('agree-terms');
     const error = document.getElementById('agree-error');
     const status = document.getElementById('form-status');

     function syncCheckboxState() {
       if (checkbox.checked) {
         checkbox.removeAttribute('aria-invalid');
         error.hidden = true;
       }
     }

     checkbox.addEventListener('change', syncCheckboxState);

     form.addEventListener('submit', (event) => {
       event.preventDefault();

       if (!checkbox.checked) {
         checkbox.setAttribute('aria-invalid', 'true');
         error.hidden = false;
         status.hidden = true;
         status.textContent = '';
         syncCheckboxState();
         checkbox.focus();
         return;
       }

       checkbox.removeAttribute('aria-invalid');
       error.hidden = true;
       status.hidden = false;
       status.textContent = 'Consent saved.';
       checkbox.focus();
     });

     syncCheckboxState();
   </script>
 </body>
 </html>

